/// <summary>One bundled hero icon: its stored slug (<c>hero:&lt;slug&gt;</c>), label, game-icons.net author and SVG path data on a 512 x 512 canvas.</summary>
public sealed record HeroGlyph(string Slug, string Label, string Author, string PathData)
{
    /// <summary>The parsed path, shared by every view that draws it.</summary>
    public Geometry Geometry => HeroGlyphs.GeometryOf(this);
}

