    /// <summary>The hero icon with this slug, or null.</summary>
    public static HeroGlyph? Find(string? slug) =>
        string.IsNullOrWhiteSpace(slug) ? null : All.FirstOrDefault(g => string.Equals(g.Slug, slug, StringComparison.Ordinal));

    internal static Geometry GeometryOf(HeroGlyph glyph) => Parsed.GetOrAdd(glyph.Slug, _ => Geometry.Parse(glyph.PathData));
}
